<?php
namespace App\Livewire\Configuracion;
use App\Models\ApiAccessScope; use App\Models\ApiAccessToken; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Livewire\Component;
class ApiAccessTokens extends Component { public bool $showForm=false; public ?int $editingId=null; public string $nombre=''; public ?string $expira_en=null; public array $scopes=[]; public ?string $tokenVisible=null; public function mount(){ $this->authorizeAccess(); } private function authorizeAccess(){ abort_unless(auth()->user()?->activeRole?->hasPermissionTo('configuracion.integraciones-api'),403); } public function nuevo(){ $this->reset(['editingId','nombre','expira_en','scopes']); $this->showForm=true; } public function editar(int $id){$this->authorizeAccess();$t=ApiAccessToken::with('scopes')->findOrFail($id);$this->editingId=$t->id;$this->nombre=$t->nombre;$this->expira_en=$t->expira_en?->format('Y-m-d');$this->scopes=$t->scopes->pluck('id')->map(fn($id)=>(string)$id)->all();$this->showForm=true;} public function guardar(){ $this->authorizeAccess(); $this->validate(['nombre'=>'required|string|max:120','expira_en'=>'nullable|date|after:today','scopes'=>'array']); if($this->editingId){$t=ApiAccessToken::findOrFail($this->editingId);DB::transaction(function()use($t){$t->update(['nombre'=>$this->nombre,'expira_en'=>$this->expira_en]);$t->scopes()->sync($this->scopes);activity()->performedOn($t)->causedBy(auth()->user())->withProperties(['prefijo'=>$t->prefijo,'alcances'=>$this->scopes])->log('Token API actualizado');});$this->reset(['editingId','nombre','expira_en','scopes']);$this->showForm=false;return;} $raw='nexo_'.Str::random(48);$token=DB::transaction(function()use($raw){$t=ApiAccessToken::create(['nombre'=>$this->nombre,'prefijo'=>substr($raw,0,12),'token_hash'=>ApiAccessToken::hashToken($raw),'created_by'=>auth()->id(),'expira_en'=>$this->expira_en]);$t->scopes()->sync($this->scopes);activity()->performedOn($t)->causedBy(auth()->user())->withProperties(['prefijo'=>$t->prefijo,'alcances'=>$this->scopes])->log('Token API creado');return $t;});$this->tokenVisible=$raw;$this->showForm=false;$this->reset(['editingId','nombre','expira_en','scopes']); } public function revocar(int $id){$this->authorizeAccess();$t=ApiAccessToken::findOrFail($id);if($t->revocado_en)return;$t->update(['revocado_en'=>now()]);activity()->performedOn($t)->causedBy(auth()->user())->withProperties(['prefijo'=>$t->prefijo])->log('Token API revocado');} public function render(){return view('livewire.configuracion.api-access-tokens',['tokens'=>ApiAccessToken::with('scopes')->latest()->get(),'catalogoScopes'=>ApiAccessScope::where('activo',true)->get()]);} }
